-- FITX Workouts v2 (1 of 6): catalogue columns, the equipment vocabulary, and per-user
-- Home and Gym equipment lists.
-- Additive only: new columns are nullable or have defaults, and two tables are new. The app keeps
-- working before this runs (it falls back to the older columns). The catalogue values themselves
-- are written by 20261118130010 (generated by scripts/catalog/build-catalog.mjs).
-- The vocabularies match src/lib/training/taxonomy.ts; tests/training/catalog-schema.test.ts checks it.

alter table public.exercise_library
  add column if not exists category text,
  add column if not exists mechanic text,
  add column if not exists muscle_group text,
  add column if not exists required_equipment text[] not null default '{}'::text[],
  add column if not exists prescription_type text not null default 'reps',
  add column if not exists default_duration_seconds integer,
  add column if not exists source_ref text,
  add column if not exists merged_into text,
  add column if not exists catalog_version smallint not null default 0;

comment on column public.exercise_library.category is 'strength, stretching, cardio, plyometrics, olympic or strongman.';
comment on column public.exercise_library.mechanic is 'compound or isolation; null where it does not apply (stretches, cardio).';
comment on column public.exercise_library.muscle_group is 'Training-level group for programme slots and filters (taxonomy.ts MUSCLE_GROUPS).';
comment on column public.exercise_library.required_equipment is 'Equipment keys (public.equipment) the movement needs; empty means none.';
comment on column public.exercise_library.prescription_type is 'reps, or time for holds, stretches and cardio.';
comment on column public.exercise_library.default_duration_seconds is 'Default work time for time-prescribed movements.';
comment on column public.exercise_library.source_ref is 'Free Exercise DB exercise id (pinned revision f00c92c7) for media and attribution.';
comment on column public.exercise_library.merged_into is 'Set on a duplicate that was merged into another row; the duplicate is hidden.';
comment on column public.exercise_library.catalog_version is '1 once the Workouts v2 clean-up has filled the columns above.';

do $$
begin
  if not exists (select 1 from pg_constraint where conname = 'exercise_library_category_check') then
    alter table public.exercise_library add constraint exercise_library_category_check
      check (category is null or category in ('strength', 'stretching', 'cardio', 'plyometrics', 'olympic', 'strongman'));
  end if;
  if not exists (select 1 from pg_constraint where conname = 'exercise_library_mechanic_check') then
    alter table public.exercise_library add constraint exercise_library_mechanic_check
      check (mechanic is null or mechanic in ('compound', 'isolation'));
  end if;
  if not exists (select 1 from pg_constraint where conname = 'exercise_library_muscle_group_check') then
    alter table public.exercise_library add constraint exercise_library_muscle_group_check
      check (muscle_group is null or muscle_group in ('chest', 'back', 'shoulders', 'biceps', 'triceps', 'forearms', 'core',
        'quadriceps', 'hamstrings', 'glutes', 'calves', 'hips', 'neck', 'full_body'));
  end if;
  if not exists (select 1 from pg_constraint where conname = 'exercise_library_prescription_type_check') then
    alter table public.exercise_library add constraint exercise_library_prescription_type_check
      check (prescription_type in ('reps', 'time'));
  end if;
  if not exists (select 1 from pg_constraint where conname = 'exercise_library_default_duration_check') then
    alter table public.exercise_library add constraint exercise_library_default_duration_check
      check (default_duration_seconds is null or default_duration_seconds between 5 and 7200);
  end if;
  if not exists (select 1 from pg_constraint where conname = 'exercise_library_merged_into_fkey') then
    alter table public.exercise_library add constraint exercise_library_merged_into_fkey
      foreign key (merged_into) references public.exercise_library (id) on delete set null;
  end if;
end $$;

create index if not exists exercise_library_category_idx on public.exercise_library (category) where is_active;
create index if not exists exercise_library_muscle_group_idx on public.exercise_library (muscle_group) where is_active;
create index if not exists exercise_library_required_equipment_idx on public.exercise_library using gin (required_equipment);

-- The equipment vocabulary: reference data, readable by everyone, written only by migrations.
create table if not exists public.equipment (
  key text primary key check (key ~ '^[a-z][a-z0-9_]{1,39}$'),
  label text not null check (char_length(label) between 1 and 80),
  kind text not null check (kind in ('free_weight', 'station', 'machine', 'accessory', 'household', 'specialty')),
  home_friendly boolean not null default false,
  synonyms text[] not null default '{}'::text[],
  sort_order smallint not null default 0
);
alter table public.equipment enable row level security;
drop policy if exists equipment_read on public.equipment;
create policy equipment_read on public.equipment for select to anon, authenticated using (true);
grant select on public.equipment to anon, authenticated;

insert into public.equipment (key, label, kind, home_friendly, synonyms, sort_order) values
  ('dumbbell', 'Dumbbells', 'free_weight', true, array['dumbbell', 'dumbbells', 'db', 'dbs', 'adjustable dumbbells']::text[], 1),
  ('kettlebell', 'Kettlebell', 'free_weight', true, array['kettlebell', 'kettlebells', 'kb']::text[], 2),
  ('barbell', 'Barbell and plates', 'free_weight', false, array['barbell', 'barbells', 'olympic bar', 'plates', 'weight plates', 'trap bar', 'hex bar']::text[], 3),
  ('ez_bar', 'EZ curl bar', 'free_weight', false, array['ez bar', 'ez-bar', 'ez curl bar', 'curl bar']::text[], 4),
  ('resistance_band', 'Resistance bands', 'accessory', true, array['band', 'bands', 'resistance band', 'resistance bands', 'loop band', 'mini band', 'tube band']::text[], 5),
  ('pull_up_bar', 'Pull-up bar', 'station', true, array['pull up bar', 'pull-up bar', 'pullup bar', 'chin up bar', 'chin-up bar', 'doorway bar']::text[], 6),
  ('bench', 'Weight bench', 'station', true, array['bench', 'flat bench', 'incline bench', 'adjustable bench', 'weight bench']::text[], 7),
  ('box', 'Plyo box or sturdy step', 'station', true, array['box', 'plyo box', 'step', 'step platform', 'aerobic step', 'stairs']::text[], 8),
  ('dip_station', 'Dip bars', 'station', false, array['dip bars', 'dip bar', 'dip station', 'parallel bars', 'dips']::text[], 9),
  ('squat_rack', 'Squat or power rack', 'station', false, array['rack', 'squat rack', 'power rack', 'squat stand', 'squat stands', 'cage']::text[], 10),
  ('cable_machine', 'Cable machine', 'machine', false, array['cable', 'cables', 'cable machine', 'cable station', 'pulley', 'functional trainer', 'cable crossover']::text[], 11),
  ('machine', 'Weight machines', 'machine', false, array['machine', 'machines', 'weight machine', 'weight machines', 'leg press', 'selectorized']::text[], 12),
  ('smith_machine', 'Smith machine', 'machine', false, array['smith', 'smith machine']::text[], 13),
  ('cardio_machine', 'Cardio machines', 'machine', false, array['cardio machine', 'cardio machines', 'treadmill', 'stationary bike', 'exercise bike', 'spin bike', 'rower', 'rowing machine', 'elliptical', 'stair climber', 'stairmaster']::text[], 14),
  ('medicine_ball', 'Medicine ball', 'accessory', true, array['medicine ball', 'med ball', 'slam ball']::text[], 15),
  ('stability_ball', 'Exercise ball', 'accessory', true, array['exercise ball', 'stability ball', 'swiss ball', 'physio ball', 'gym ball']::text[], 16),
  ('foam_roller', 'Foam roller', 'accessory', true, array['foam roller', 'roller']::text[], 17),
  ('jump_rope', 'Jump rope', 'accessory', true, array['jump rope', 'skipping rope', 'skip rope']::text[], 18),
  ('suspension_trainer', 'Suspension trainer or rings', 'accessory', true, array['suspension trainer', 'trx', 'rings', 'gymnastic rings']::text[], 19),
  ('chair', 'Sturdy chair', 'household', true, array['chair', 'sturdy chair']::text[], 20),
  ('sled', 'Sled', 'specialty', false, array['sled', 'prowler']::text[], 21),
  ('strongman_implements', 'Strongman implements', 'specialty', false, array['strongman', 'atlas stone', 'yoke', 'log', 'tire', 'tyre', 'keg']::text[], 22),
  ('specialty', 'Other specialist gym equipment', 'specialty', false, array['other', 'specialty']::text[], 23)
on conflict (key) do update set label = excluded.label, kind = excluded.kind, home_friendly = excluded.home_friendly,
  synonyms = excluded.synonyms, sort_order = excluded.sort_order;

-- What each user has at home and at their gym. No row means "not set yet": the app then starts from
-- the onboarding/Profile equipment at home and from a full commercial gym.
create table if not exists public.user_equipment_profiles (
  user_id uuid not null references auth.users (id) on delete cascade,
  context text not null check (context in ('home', 'gym')),
  equipment_keys text[] not null default '{}'::text[] check (cardinality(equipment_keys) <= 64),
  updated_at timestamptz not null default now(),
  primary key (user_id, context)
);
alter table public.user_equipment_profiles enable row level security;
drop policy if exists user_equipment_profiles_owner on public.user_equipment_profiles;
create policy user_equipment_profiles_owner on public.user_equipment_profiles for all to authenticated
  using ((select auth.uid()) = user_id) with check ((select auth.uid()) = user_id);
grant select, insert, update, delete on public.user_equipment_profiles to authenticated;
